const b = $json.body || $json;
const to = String(b.whatsapp || b.to || '').trim();
const cliente = String(b.cliente || '').trim();
const plantilla = String(b.plantilla || 'post_audit').trim();
const mensajes = {
  post_audit: `Hola${cliente ? ' — ' + cliente : ''}: ya tenés el informe de auditoría. Si querés, te paso los planes Básico / Presencia / Completo.`,
  oferta_plan: `Te dejo los planes: Básico (quick wins), Presencia (web+GBP), Completo (+Wasap). ¿Cuál te sirve?`,
  cierre: `Cuando quieras avanzamos con el plan que elijas. Sin compromiso en la auditoría.`
};
const texto = mensajes[plantilla] || mensajes.post_audit;
if (!to) {
  return [{ json: { ok: false, error: 'falta whatsapp', texto } }];
}
return [{ json: {
  ok: true,
  sistema: '06-auditorias-locales',
  etapa: 'seguimiento',
  to,
  plantilla,
  texto,
  status: 'draft_ready',
  todo: 'TODO_CREDENCIAL: enviar vía Meta Cloud API / proveedor Wasap',
  at: new Date().toISOString()
}}];
